cat > /tmp/model.pl <<'EOF'
sub hum { my $s=shift; $s =~ s/_/ /g; if(length($s)){ substr($s,0,1) = uc_ascii(substr($s,0,1)); } return $s; }
sub uc_ascii { my $c=shift; my $o=ord($c); return ($o>=0x61 && $o<=0x7a) ? chr($o-32) : $c; }
sub lc_ascii { my $c=shift; my $o=ord($c); return ($o>=0x41 && $o<=0x5a) ? chr($o+32) : $c; }
sub tit { my $s=shift; my $cap=1; my $out=""; for my $i (0..length($s)-1){ my $c=substr($s,$i,1);
  if($c eq " "){ $out.=" "; $cap=1; } elsif($cap){ $out.=uc_ascii($c); $cap=0; } else { $out.=lc_ascii($c); } }
  return $out; }
1;
EOF
